// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// 本域进程存活
	// (GET /healthz)
	Health(ctx context.Context, request HealthRequestObject) (HealthResponseObject, error)
	// 本域启动/恢复就绪
	// (GET /readyz)
	Ready(ctx context.Context, request ReadyRequestObject) (ReadyResponseObject, error)
	// 取得jobs本域屏障
	// (POST /v1/barriers)
	AcquireBarrier(ctx context.Context, request AcquireBarrierRequestObject) (AcquireBarrierResponseObject, error)
	// 解除全域任务暂停
	// (POST /v1/barriers/{barrierId}:release)
	ReleaseBarrier(ctx context.Context, request ReleaseBarrierRequestObject) (ReleaseBarrierResponseObject, error)
	// 等待全域安全点
	// (POST /v1/barriers:coordinate)
	CoordinateBarrier(ctx context.Context, request CoordinateBarrierRequestObject) (CoordinateBarrierResponseObject, error)
	// 查看死信投递
	// (GET /v1/deliveries)
	ListDeliveries(ctx context.Context, request ListDeliveriesRequestObject) (ListDeliveriesResponseObject, error)
	// 重放死信投递
	// (POST /v1/deliveries/{deliveryId}:replay)
	ReplayDelivery(ctx context.Context, request ReplayDeliveryRequestObject) (ReplayDeliveryResponseObject, error)
	// 持久接收事件
	// (POST /v1/events)
	PublishEvent(ctx context.Context, request PublishEventRequestObject) (PublishEventResponseObject, error)
	// 消费者确认投递
	// (POST /v1/events/{eventId}:ack)
	AcknowledgeEvent(ctx context.Context, request AcknowledgeEventRequestObject) (AcknowledgeEventResponseObject, error)
	// 已登记消费者订阅事件SSE
	// (GET /v1/events:subscribe)
	SubscribeEvents(ctx context.Context, request SubscribeEventsRequestObject) (SubscribeEventsResponseObject, error)
	// 查看任务队列
	// (GET /v1/jobs)
	ListJobs(ctx context.Context, request ListJobsRequestObject) (ListJobsResponseObject, error)
	// 持久提交任务
	// (POST /v1/jobs)
	CreateJob(ctx context.Context, request CreateJobRequestObject) (CreateJobResponseObject, error)
	// 读取管理任务状态
	// (GET /v1/jobs/{jobId})
	ReadJob(ctx context.Context, request ReadJobRequestObject) (ReadJobResponseObject, error)
	// 写回前检验执行权
	// (GET /v1/jobs/{jobId}/lease)
	CheckLease(ctx context.Context, request CheckLeaseRequestObject) (CheckLeaseResponseObject, error)
	// 任务进度SSE
	// (GET /v1/jobs/{jobId}/progress)
	StreamProgress(ctx context.Context, request StreamProgressRequestObject) (StreamProgressResponseObject, error)
	// 请求取消任务
	// (POST /v1/jobs/{jobId}:cancel)
	CancelJob(ctx context.Context, request CancelJobRequestObject) (CancelJobResponseObject, error)
	// 提交成功结果
	// (POST /v1/jobs/{jobId}:complete)
	CompleteJob(ctx context.Context, request CompleteJobRequestObject) (CompleteJobResponseObject, error)
	// 失败写回
	// (POST /v1/jobs/{jobId}:fail)
	FailJob(ctx context.Context, request FailJobRequestObject) (FailJobResponseObject, error)
	// 维持租约
	// (POST /v1/jobs/{jobId}:heartbeat)
	HeartbeatJob(ctx context.Context, request HeartbeatJobRequestObject) (HeartbeatJobResponseObject, error)
	// 重试失败任务
	// (POST /v1/jobs/{jobId}:retry)
	RetryJob(ctx context.Context, request RetryJobRequestObject) (RetryJobResponseObject, error)
	// 确认开始执行
	// (POST /v1/jobs/{jobId}:start)
	StartJob(ctx context.Context, request StartJobRequestObject) (StartJobResponseObject, error)
	// 领取待执行任务
	// (POST /v1/jobs:claim)
	ClaimJob(ctx context.Context, request ClaimJobRequestObject) (ClaimJobResponseObject, error)
	// 查看定时任务
	// (GET /v1/schedules)
	ListSchedules(ctx context.Context, request ListSchedulesRequestObject) (ListSchedulesResponseObject, error)
	// 创建定时任务
	// (POST /v1/schedules)
	CreateSchedule(ctx context.Context, request CreateScheduleRequestObject) (CreateScheduleResponseObject, error)
	// 修改定时CAS
	// (PUT /v1/schedules/{scheduleId})
	UpdateSchedule(ctx context.Context, request UpdateScheduleRequestObject) (UpdateScheduleResponseObject, error)
	// 受控读取已完成域快照归档
	// (GET /v1/snapshots/{snapshotId}/archive)
	ReadSnapshotArchive(ctx context.Context, request ReadSnapshotArchiveRequestObject) (ReadSnapshotArchiveResponseObject, error)
	// 删除恢复暂存或换出的旧数据目录
	// (POST /v1/snapshots:discard)
	DiscardSnapshot(ctx context.Context, request DiscardSnapshotRequestObject) (DiscardSnapshotResponseObject, error)
	// 导出队列与事件一致快照
	// (POST /v1/snapshots:export)
	ExportSnapshot(ctx context.Context, request ExportSnapshotRequestObject) (ExportSnapshotResponseObject, error)
	// 暂存本域恢复归档，不改active目录
	// (POST /v1/snapshots:stage)
	StageSnapshot(ctx context.Context, request StageSnapshotRequestObject) (StageSnapshotResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// Health operation middleware
func (sh *strictHandler) Health(w http.ResponseWriter, r *http.Request) {
	var request HealthRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.Health(ctx, request.(HealthRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "Health")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(HealthResponseObject); ok {
		if err := validResponse.VisitHealthResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

// Ready operation middleware
